`,d.jsx(e.h3,{children:"The Vector Index Invoice"}),`
`,d.jsxs(e.blockquote,{children:[`
`,d.jsxs(e.ul,{children:[`
`,d.jsxs(e.li,{children:[d.jsx(e.strong,{children:"Paid With:"})," Loss of absolute precision (Recall trade-offs), high memory utilization (the graph must reside in RAM), and slow index build times."]}),`
`,d.jsxs(e.li,{children:[d.jsx(e.strong,{children:"Bought:"})," Millisecond-level semantic and similarity searches across high-dimensional data pools."]}),`
`]}),`
`]}),`
